"""Public entry points for an imported receipt sequence."""
from .ingest.csv_rows import read_receipts
from .reporting.totals import Totals
from .state.registry import Registry


def summarize_csv(text: str) -> list[dict]:
    registry = Registry()
    totals = Totals()
    for receipt in read_receipts(text):
        change = registry.accept(receipt)
        if change is not None:
            totals.apply(change)
    return totals.rows()


def latest_receipts(text: str):
    registry = Registry()
    for receipt in read_receipts(text):
        registry.accept(receipt)
    return registry.latest()

"""Select the current revision of each independent ticket."""
from ..records import Change, Receipt


class Registry:
    def __init__(self):
        self._receipts: dict[str, Receipt] = {}

    def accept(self, receipt: Receipt) -> Change | None:
        before = self._receipts.get(receipt.ticket)
        if before is not None:
            if receipt.revision < before.revision:
                return None
            if receipt.revision == before.revision:
                if receipt != before:
                    raise ValueError("conflicting current revision")
                return None
        self._receipts[receipt.ticket] = receipt
        return Change(before, receipt)

    def latest(self) -> list[Receipt]:
        return [self._receipts[ticket] for ticket in sorted(self._receipts)]

"""Maintain the report while accepted revisions arrive."""
from ..records import Change
from .entries import bucket, contributions


class Totals:
    def __init__(self):
        self._units: dict[tuple[str, str], int] = {}

    def apply(self, change: Change) -> None:
        destination = bucket(change.after)
        for receipt, units in contributions(change):
            self._units[destination] = self._units.get(destination, 0) + units
            if self._units[destination] == 0:
                del self._units[destination]

    def rows(self) -> list[dict]:
        return [{"depot": depot, "item": item, "units": units}
                for (depot, item), units in sorted(self._units.items())]

"""Signed contributions for a receipt revision transition."""
from ..records import Change, Receipt


def bucket(receipt: Receipt) -> tuple[str, str]:
    return receipt.depot, receipt.item


def contributions(change: Change) -> list[tuple[Receipt, int]]:
    entries = []
    if change.before is not None and change.before.status == "active":
        entries.append((change.before, -change.before.units))
    if change.after.status == "active":
        entries.append((change.after, change.after.units))
    return entries

